CREATE TABLE leave_profile(employee_id uuid PRIMARY KEY REFERENCES employee(id), input jsonb NOT NULL, verified_by text NOT NULL REFERENCES "user"(id));
CREATE TABLE leave_grant(employee_id uuid NOT NULL REFERENCES employee(id),vintage integer NOT NULL,units integer NOT NULL CHECK(units BETWEEN 0 AND 28),status text NOT NULL CHECK(status IN ('projected','active')),PRIMARY KEY(employee_id,vintage));
CREATE TABLE leave_request(id uuid PRIMARY KEY,employee_id uuid NOT NULL REFERENCES employee(id),actor_id text NOT NULL REFERENCES "user"(id),request_key text NOT NULL,input_hash text NOT NULL,input jsonb NOT NULL,kind text NOT NULL,state text NOT NULL CHECK(state IN ('pending','approved','rejected','cancelled')),revision integer NOT NULL DEFAULT 1,slots jsonb NOT NULL,UNIQUE(actor_id,request_key));
CREATE TABLE leave_allocation(employee_id uuid NOT NULL REFERENCES employee(id),request_id uuid NOT NULL REFERENCES leave_request(id),date text NOT NULL,part text NOT NULL CHECK(part IN ('am','pm')),vintage integer NOT NULL,PRIMARY KEY(employee_id,date,part),FOREIGN KEY(employee_id,vintage) REFERENCES leave_grant(employee_id,vintage));
-- A later payroll workflow may supply settled-period markers. This slice never pays or changes payroll history.
CREATE TABLE leave_closed_period(employee_id uuid NOT NULL REFERENCES employee(id),month text NOT NULL,reference text NOT NULL,PRIMARY KEY(employee_id,month));
CREATE TABLE leave_payroll_hold(employee_id uuid NOT NULL REFERENCES employee(id),month text NOT NULL,request_key text NOT NULL,reason text NOT NULL,PRIMARY KEY(employee_id,month,request_key));
